DROP POLICY insert_scope ON mos.review_cases;
CREATE POLICY insert_scope ON mos.review_cases FOR INSERT TO mos_app,mos_worker WITH CHECK (
 mos.brand_member(brand_code) AND state='SUBMITTED' AND submitted_by=mos.current_claims()->>'actorId'
 AND ((subject_type='content_version' AND mos.has_permission('content.submit')) OR (subject_type='asset_admission' AND mos.has_permission('asset.submit'))));
DROP POLICY insert_scope ON mos.review_decisions;
CREATE POLICY insert_scope ON mos.review_decisions FOR INSERT TO mos_app,mos_worker WITH CHECK (
 mos.brand_member(brand_code) AND actor_id=mos.current_claims()->>'actorId' AND EXISTS(
 SELECT 1 FROM mos.review_cases c WHERE c.id=case_id AND c.brand_code=review_decisions.brand_code AND c.version_hash=review_decisions.version_hash
 AND ((action='CANCEL' AND mos.has_permission('content.edit')) OR
 (c.submitted_by<>actor_id AND ((c.type='PROFESSIONAL_REVIEW' AND mos.has_permission('content.professional_review'))
 OR(c.type='PUBLICATION_APPROVAL' AND mos.has_permission('content.publish_approve')) OR(c.type='ASSET_ADMISSION' AND mos.has_permission('library.asset.approve.final')))))));
ALTER TABLE mos.source_evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE mos.source_evidence FORCE ROW LEVEL SECURITY;
GRANT SELECT ON mos.source_evidence TO mos_app,mos_worker,mos_guard;
GRANT INSERT ON mos.source_evidence,mos.research_report_evidence TO mos_guard;
GRANT SELECT ON mos.research_reports,mos.research_report_evidence,mos.source_registry TO mos_guard;
CREATE POLICY evidence_read ON mos.source_evidence FOR SELECT TO mos_app,mos_worker,mos_guard USING (EXISTS(SELECT 1 FROM mos.research_report_evidence r WHERE r.evidence_id=source_evidence.id));
CREATE POLICY evidence_guard_insert ON mos.source_evidence FOR INSERT TO mos_guard WITH CHECK (mos.has_permission('research.create'));
CREATE POLICY report_guard_read ON mos.research_reports FOR SELECT TO mos_guard USING (mos.brand_member(brand_code));
CREATE POLICY registry_guard_read ON mos.source_registry FOR SELECT TO mos_guard USING (mos.brand_member(brand_code));
CREATE POLICY report_evidence_guard ON mos.research_report_evidence TO mos_guard USING (mos.brand_member(brand_code)) WITH CHECK (mos.brand_member(brand_code) AND mos.has_permission('research.create'));
CREATE FUNCTION mos.add_source_evidence(report text,eid text,url_value text,title_value text,source text DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mos AS $$
DECLARE c jsonb:=mos.current_claims();b text:=c->>'brandCode';
BEGIN
 IF NOT mos.has_permission('research.create') OR NOT EXISTS(SELECT 1 FROM mos.research_reports WHERE id=report AND brand_code=b) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='EVIDENCE_ACCESS_DENIED'; END IF;
 IF source IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mos.source_registry WHERE id=source AND brand_code=b) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='EVIDENCE_SOURCE_DENIED'; END IF;
 IF eid IS NULL OR eid='' OR url_value IS NULL OR url_value='' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='INVALID_EVIDENCE'; END IF;
 INSERT INTO mos.source_evidence(id,url,title,source_id,license_state,access_state,created_at) VALUES(eid,url_value,title_value,source,'UNKNOWN','UNKNOWN',CURRENT_TIMESTAMP);
 INSERT INTO mos.research_report_evidence(id,brand_code,report_id,evidence_id,ordinal,created_at) VALUES(eid||':'||report,b,report,eid,0,CURRENT_TIMESTAMP);
END $$;
GRANT CREATE ON SCHEMA mos TO mos_guard;
ALTER FUNCTION mos.add_source_evidence(text,text,text,text,text) OWNER TO mos_guard;
REVOKE CREATE ON SCHEMA mos FROM mos_guard;
REVOKE ALL ON FUNCTION mos.add_source_evidence(text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mos.add_source_evidence(text,text,text,text,text) TO mos_app,mos_worker;
-- Linking an already-hidden global evidence ID would leak another brand's source metadata.
REVOKE INSERT,UPDATE,DELETE ON mos.research_report_evidence FROM mos_app,mos_worker;
REVOKE DELETE ON mos.review_cases FROM mos_app,mos_worker;
DROP POLICY update_scope ON mos.review_cases;
CREATE POLICY update_scope ON mos.review_cases FOR UPDATE TO mos_app,mos_worker USING (
 mos.brand_member(brand_code) AND (mos.has_permission('content.edit') OR
 (submitted_by<>mos.current_claims()->>'actorId' AND ((type='PROFESSIONAL_REVIEW' AND mos.has_permission('content.professional_review')) OR (type='PUBLICATION_APPROVAL' AND mos.has_permission('content.publish_approve')) OR (type='ASSET_ADMISSION' AND mos.has_permission('library.asset.approve.final'))))))
WITH CHECK (mos.brand_member(brand_code) AND ((state='CANCELLED' AND mos.has_permission('content.edit')) OR
 (submitted_by<>mos.current_claims()->>'actorId' AND ((type='PROFESSIONAL_REVIEW' AND mos.has_permission('content.professional_review')) OR (type='PUBLICATION_APPROVAL' AND mos.has_permission('content.publish_approve')) OR (type='ASSET_ADMISSION' AND mos.has_permission('library.asset.approve.final'))))));
DROP POLICY sensitive_insert ON mos.audit_events;
CREATE POLICY sensitive_insert ON mos.audit_events FOR INSERT TO mos_app,mos_worker WITH CHECK (
 (mos.brand_member(brand_code) OR (brand_code IS NULL AND mos.has_permission('settings.manage')))
 AND ((actor_user_id=mos.current_claims()->>'actorId' AND (actor_ref IS NULL OR actor_ref=mos.current_claims()->>'actorId')) OR (mos.has_permission('settings.manage') AND actor_user_id IS NULL)));
DROP POLICY sensitive_insert ON mos.provider_calls;
CREATE POLICY sensitive_insert ON mos.provider_calls FOR INSERT TO mos_app,mos_worker WITH CHECK (
 (mos.brand_member(brand_code) AND mos.has_permission('model.invoke') AND actor_id=mos.current_claims()->>'actorId') OR (brand_code IS NULL AND mos.has_permission('settings.manage')));
RESET ROLE;
